package com.expensetracker.controller;
import com.expensetracker.dto.*;import com.expensetracker.enums.TransactionType;import com.expensetracker.service.TransactionService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/transactions") public class TransactionController {private final TransactionService s;public TransactionController(TransactionService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public TransactionResponseDTO create(@Valid @RequestBody TransactionRequestDTO r){return s.create(r);}@GetMapping public Page<TransactionResponseDTO> search(@RequestParam Long userId,@RequestParam(required=false) TransactionType type,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) LocalDate startDate,@RequestParam(required=false) LocalDate endDate,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="date") String sortBy,@RequestParam(defaultValue="DESC") String direction){return s.search(userId,type,categoryId,startDate,endDate,page,size,sortBy,direction);}@GetMapping("/{id}") public TransactionResponseDTO get(@PathVariable Long id,@RequestParam Long userId){return s.get(id,userId);}@PutMapping("/{id}") public TransactionResponseDTO update(@PathVariable Long id,@Valid @RequestBody TransactionRequestDTO r){return s.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@RequestParam Long userId){s.delete(id,userId);}}
